<?php require 'common.php';require_admin();$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT)?:0;$p=['title'=>'','description'=>'','stack'=>'','url'=>'','image'=>'','sort_order'=>0];if($id){$stmt=$db->prepare('SELECT * FROM projects WHERE id=?');$stmt->execute([$id]);$p=$stmt->fetch(PDO::FETCH_ASSOC);if(!$p){http_response_code(404);exit('Project not found');}}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$p=['title'=>trim((string)($_POST['title']??'')),'description'=>trim((string)($_POST['description']??'')),'stack'=>trim((string)($_POST['stack']??'')),'url'=>trim((string)($_POST['url']??'')),'image'=>trim((string)($_POST['image']??'')),'sort_order'=>(int)($_POST['sort_order']??0)];if($p['title']==='')$error='Project title is required.';elseif($p['url']!=='' && !project_url($p['url']))$error='Enter an existing projects/folder/index.php or a full https:// URL';elseif($p['image']!=='' && !safe_image_url($p['image']))$error='Enter an existing projects/folder/assets/image.png or a full http(s) image URL';else{$values=array_values($p);if($id){$stmt=$db->prepare('UPDATE projects SET title=?,description=?,stack=?,url=?,image=?,sort_order=? WHERE id=?');$values[]=$id;}else{$stmt=$db->prepare('INSERT INTO projects(title,description,stack,url,image,sort_order) VALUES(?,?,?,?,?,?)');}$stmt->execute($values);header('Location: projects.php');exit;}}layout_start($id?'Edit project':'Add a project');?><div class="panel narrow wide"><p class="sub">Website projects, school systems, designs, and applications all belong here.</p><?php if($error):?><p class="error"><?=h($error)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>Project name<input name="title" value="<?=h($p['title'])?>" required maxlength="150" placeholder="My Website Project"></label><label>Description<textarea name="description" rows="5" placeholder="What does your project do?"><?=h($p['description'])?></textarea></label><label>Technologies<input name="stack" value="<?=h($p['stack'])?>" placeholder="PHP, MySQL, JavaScript"></label><label>Project URL or local path<input type="text" name="url" value="<?=h($p['url'])?>" placeholder="projects/my-website/index.php or https://example.com"></label><p class="sub">Local websites open inside the portfolio window. Copy your files into the projects folder first. External sites open in a new tab.</p><label>Preview image URL (optional)<input type="text" name="image" value="<?=h($p['image'])?>" placeholder="projects/my-website/assets/preview.png or https://example.com/image.png"></label><label>Display order<input type="number" name="sort_order" value="<?=(int)$p['sort_order']?>"></label><div class="actions"><button class="primary">Save project</button><a class="secondary" href="projects.php">Cancel</a></div></form></div><?php layout_end(); ?>
